-- OPTION BANKS (Sam, 2026-11-23: Malachar and the main NPCs "must use [their] agentic AI intelligence for things that
-- are required, otherwise from informational files to save tokens"). PR 2 of 3; design: claude/Malachar_Options_2026-11-23.md.
--   npc_agents.option_bank  options already written and tagged (lib/option-bank.ts), tried before any model call
--   suggestion_sets.source  "bank" or "model", so The Cast shows how often the files answered
-- Additive. Seeds only banks that are still empty, so an edit Sam made on The Cast is never overwritten.
-- Seed wording: Claude's, from the cards and the pen as built (plate "11" is the Slave Pen). Sam edits on The Cast > Actor.
alter table public.npc_agents add column if not exists option_bank jsonb not null default '[]'::jsonb;
alter table public.suggestion_sets add column if not exists source text not null default 'model';
update public.npc_agents set option_bank = $bank$[{"text":"Test the gate's bars for a loose bolt","skill":"Athletics","when":{"plates":["11"],"fight":false,"talking":false}},{"text":"Count the guards and time their rounds","skill":"Perception","when":{"plates":["11"],"fight":false,"talking":false}},{"text":"Ask Eldeth what she has seen of the guards","skill":"Insight","when":{"plates":["11"],"fight":false,"talking":false,"with":["eldeth"]}},{"text":"Ask Jimjar what odds he gives on escape","skill":"Persuasion","when":{"plates":["11"],"fight":false,"talking":false,"with":["jimjar"]}},{"text":"Ask Buppido to keep watch while you sleep","skill":null,"bait":true,"when":{"plates":["11"],"fight":false,"talking":false,"with":["buppido"]}},{"text":"Rattle the bars and demand water","skill":"Intimidation","bait":true,"when":{"plates":["11"],"fight":false,"talking":false}},{"text":"Study the pen in the dim light","skill":"Perception","observe":true,"when":{"plates":["11"],"fight":false,"talking":false}},{"text":"Put your back to the wall beside Eldeth","skill":null,"when":{"fight":true,"with":["eldeth"]}},{"text":"Shout for the others to close on the gate","skill":null,"when":{"plates":["battle-pen-gate"],"fight":true}},{"text":"Chase the guard who runs for the bridge","skill":"Athletics","bait":true,"when":{"plates":["battle-pen-gate"],"fight":true}},{"text":"Watch where the next guard comes from","skill":"Perception","observe":true,"when":{"fight":true}},{"text":"Ask him what he wants from you","skill":"Insight","when":{"talking":true}},{"text":"Ask him: why us?","skill":"Insight","when":{"talking":true}},{"text":"Tell him you are not afraid of him","skill":"Intimidation","when":{"talking":true}},{"text":"Offer him a bargain for your freedom","skill":"Persuasion","bait":true,"when":{"talking":true}},{"text":"Study what you can see of him","skill":"Perception","observe":true,"when":{"talking":true}}]$bank$::jsonb where key = 'malachar' and option_bank = '[]'::jsonb;
update public.npc_agents set option_bank = $bank$[{"text":"Ask Eldeth what her plan is","skill":"Insight","when":{"talking":true}},{"text":"Promise to get her home to Gauntlgrym","skill":"Persuasion","when":{"talking":true}},{"text":"Ask what she makes of Ront","skill":"Insight","when":{"talking":true,"with":["ront"]}},{"text":"Agree to rush the guards with her now","skill":"Athletics","bait":true,"when":{"talking":true,"fight":false}},{"text":"Watch the guards while she talks","skill":"Perception","observe":true,"when":{"talking":true}}]$bank$::jsonb where key = 'eldeth' and option_bank = '[]'::jsonb;
update public.npc_agents set option_bank = $bank$[{"text":"Tell Ront to keep his voice down","skill":"Intimidation","when":{"talking":true}},{"text":"Ask Ront how many drow he counted","skill":"Persuasion","when":{"talking":true}},{"text":"Ask why he hates the dwarf","skill":"Insight","when":{"talking":true,"with":["eldeth"]}},{"text":"Let Ront lead when the gate opens","skill":null,"bait":true,"when":{"talking":true}},{"text":"Keep an eye on the gate while he talks","skill":"Perception","observe":true,"when":{"talking":true}}]$bank$::jsonb where key = 'ront' and option_bank = '[]'::jsonb;
update public.npc_agents set option_bank = $bank$[{"text":"Ask the prince what he saw at the gate","skill":"Persuasion","when":{"talking":true}},{"text":"Look closely at the prince's hands","skill":"Insight","when":{"talking":true}},{"text":"Ask how he came to be taken","skill":"Insight","when":{"talking":true}},{"text":"Swear to escort him home to Nelrindenvane","skill":"Persuasion","bait":true,"when":{"talking":true}},{"text":"Look around while he holds forth","skill":"Perception","observe":true,"when":{"talking":true}}]$bank$::jsonb where key = 'derendil' and option_bank = '[]'::jsonb;
update public.npc_agents set option_bank = $bank$[{"text":"Ask what odds he gives on the gate","skill":"Persuasion","when":{"talking":true}},{"text":"Ask what he would stake his help on","skill":"Persuasion","when":{"talking":true}},{"text":"Tell him to show his coin first","skill":"Insight","when":{"talking":true}},{"text":"Take his bet on who dies first","skill":null,"bait":true,"when":{"talking":true}},{"text":"Watch his hands while he talks","skill":"Perception","observe":true,"when":{"talking":true}}]$bank$::jsonb where key = 'jimjar' and option_bank = '[]'::jsonb;
update public.npc_agents set option_bank = $bank$[{"text":"Ask what his little idea is","skill":"Persuasion","when":{"talking":true}},{"text":"Ask why he smiles so much","skill":"Insight","when":{"talking":true}},{"text":"Thank him and step away","skill":null,"when":{"talking":true}},{"text":"Agree to a quiet word, just the two of you","skill":null,"bait":true,"when":{"talking":true}},{"text":"Watch the others while he talks","skill":"Perception","observe":true,"when":{"talking":true}}]$bank$::jsonb where key = 'buppido' and option_bank = '[]'::jsonb;
update public.npc_agents set option_bank = $bank$[{"text":"Ask Jorlan what he wants for the key","skill":"Persuasion","when":{"talking":true}},{"text":"Ask why he hates Ilvara","skill":"Insight","when":{"talking":true}},{"text":"Ask when the next watch changes","skill":"Insight","when":{"talking":true}},{"text":"Tell Jorlan the whole plan","skill":null,"bait":true,"when":{"talking":true}},{"text":"Watch the walkway behind him","skill":"Perception","observe":true,"when":{"talking":true}}]$bank$::jsonb where key = 'jorlan' and option_bank = '[]'::jsonb;
